(()=>{'use strict';const HREF='/astrologie-cariera-vocatie/';const CASE11='/studii-de-caz/acte-casa-septembrie-2004/';const IMAGE='/assets/vocatie-astrolog-slider-20261027.webp';const ensureStyle=()=>{if(document.getElementById('av-case12-vocation-style'))return;const s=document.createElement('style');s.id='av-case12-vocation-style';s.textContent=`#studii-de-caz-home .av-case-vocation .av-case-showcase-visual img,html.av-ultra-home-production.av-cardless-home body:not(.guide-page) #studii-de-caz-home .av-case-desktop-marquee-v9 .av-case-vocation .av-case-showcase-visual img,html.av-ultra-home-production.av-cardless-home body:not(.guide-page) #studii-de-caz-home .av-case-mobile-ticker .av-case-vocation .av-case-showcase-visual img{object-fit:contain!important;object-position:center!important;background:#030705!important}`;document.head.appendChild(s)};const notify=section=>section.dispatchEvent(new CustomEvent('astrovip:cases-expanded',{bubbles:true,detail:{case:12}}));const install=async()=>{const section=document.getElementById('studii-de-caz-home');const track=section&&section.querySelector('.av-case-showcase-grid');if(!section||!track)return false;if(track.querySelector(`a[href="${HREF}"]`))return true;if(!track.querySelector(`a[href="${CASE11}"]`))return false;ensureStyle();const a=document.createElement('a');a.className='av-case-showcase-card av-case-local-space av-case-vocation';a.href=HREF;a.setAttribute('aria-label','Vezi studiul de caz Vocația profesională — Astrolog');a.innerHTML=`<div class="av-case-showcase-visual av-case-local-space-visual"><img src="${IMAGE}" width="640" height="360" loading="lazy" decoding="async" alt="Vocația profesională — Astrolog, studiu de caz AstroVip"><span class="av-case-local-space-symbol" aria-hidden="true">♄</span><span class="av-case-local-space-index" aria-hidden="true">12</span></div><div class="av-case-showcase-copy"><p class="av-case-showcase-eyebrow">STUDIU DE CAZ 12 · VOCAȚIE</p><h3>Vocația profesională — Astrolog</h3><p class="av-case-showcase-meta">MC în Capricorn · Saturn în Leu · Casa 5</p><p class="av-case-showcase-lead">Soarele în Pești, Neptun oriental și midpointul Neptun/Pluto conturează simbolic direcția profesională astrologică.</p><span class="av-case-showcase-cta">VEZI STUDIUL →</span></div>`;track.appendChild(a);notify(section);return true};const boot=()=>{let tries=0;const timer=setInterval(()=>{tries++;Promise.resolve(install()).then(done=>{if(done||tries>120)clearInterval(timer)})},100);install()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();})();